# Native phase diagnostics on the same actual mortgage facility.
if(!exists('estimate_multistate_transitions'))library(creditratingsystem)
run_mortgage_phase_review<-function(data=NULL,verify_reference=TRUE,return_artifacts=FALSE,upstream=NULL,house_data=NULL,life_data=NULL){
 load_data<-function(n)jsonlite::fromJSON(system.file(paste0('extdata/',n,'.json'),package='creditratingsystem'),simplifyVector=FALSE)
 if(is.null(data))data<-load_data('mortgage_phase_review')
 life<-if(is.null(life_data))load_data('mortgage_lifecycle')else life_data;house<-if(is.null(house_data))load_data('mortgage_household_review')else house_data
 if(is.null(upstream)){sys.source(system.file('examples/mortgage_household_review.R',package='creditratingsystem'),envir=environment());raw<-run_mortgage_household_review(return_artifacts=TRUE)}else raw<-upstream
 stopifnot(data$facility_id=='facility_A');assessment<-raw$governance$assessment
 fresh<-check_assessment_freshness(assessment,list(maximum_age_days=365,maximum_information_age_days=365,trigger_types=list('payment_delay')),list(list(event_id='facility_A-Aug31-due',subject_id='customer_A',type='payment_delay',occurred_at='2024-08-31',known_at='2024-08-31')),'2024-08-31','2024-08-31')$value
 pool<-house$pool;drift<-detect_credit_feature_drift(lapply(pool$fit$observations,function(r)list(score=r$score)),lapply(pool$assignment_inputs$observations,function(r)list(score=r$score)),feature_order='score',method='psi',permutations=NULL,multiple_testing='not_applicable',dependence_assumption='descriptive',frozen_bins=list(score=list(kind='numeric',cutpoints=50,support=c(0,100))))$value
 forecast<-raw$pool_inputs$predictions[[1]];pd<-forecast$pd;residual<-1-pd
 calibration<-detect_pd_calibration_drift(list(list(time='2025-02-04',value=residual,mature=TRUE)),method='ewma',parameters=list(smoothing=.5),null_paths=matrix(vapply(data$null_uniforms,function(u)as.numeric(u<pd)-pd,0.),ncol=1),null_spec=list(model_id=forecast$model_id,model_version='1',calibration_id='declared-one-step-Bernoulli-null',residual_scale='observed_minus_expected_rate',dependence='prespecified_dependent',probability_measure='PHYSICAL',calibrated_before='2024-02-03'),alpha=.05)$value
 panel<-raw$retail$account_panel;panel[[2]]$state<-'DELINQUENT';roll<-estimate_retail_roll_rates(panel,states=c('ACTIVE','DELINQUENT','DEFAULT'),from_date='2024-08-31',to_date='2024-09-30',group_by=character(),weighting='count',missing_successor='error')$value
 tr<-data$cure_training;last<-as.Date(tr$calendar_origin)+max(vapply(tr$rows,function(r)r$stop,0.));stopifnot(last<=as.Date(tr$observation_end),tr$observation_end<=tr$training$known_at,tr$training$known_at<'2024-09-01')
 fitted<-estimate_multistate_transitions(tr$rows,states=c('D','C'),allowed_transitions=list(list('D','C'),list('C','D')),initial_state='D',target=tr$target,training=tr$training,model_id='shared-prior-cure',model_version='1');model<-fitted$model;model$collections_contract<-list(cure_states=list('C'),default_states=list('D'),supported_actions=list('baseline'),supported_initial_states=list('D','C'),action_interpretation='observational_conditioning')
 cure<-predict_cure_and_redefault(current_episode=list(episode_id=data$open_episode$episode_id,state='D',model_time=0,known_at='2024-09-02',ever_default=TRUE),model=model,action_conditions=list(action_id='baseline',assumption_reference=data$assumption_reference),horizon_grid=c(0,30,60),state_recoveries=matrix(c(0,0,0,.8*life$default_ead,0,0),nrow=3,byrow=TRUE),target=tr$target,currency='EUR')$value
 cc<-life$collections;episodes<-build_collections_episodes(cc$states,cc$actions,evaluation_cutoff='2025-03-01',coverage=cc$coverage,episode_rule=cc$episode_rule)$value;targets<-build_cure_targets(episodes,horizon_days=365,redefault_horizon_days=90,evaluation_cutoff='2025-03-01')$value
 comp<-data$competing;last<-as.Date(comp$calendar_origin)+max(vapply(comp$rows,function(r)r$stop,0.));stopifnot(last<=as.Date(comp$observation_end),comp$observation_end<=comp$training$known_at,comp$training$known_at<'2024-02-03')
 cause<-fit_cause_specific_hazards(comp$rows,matrix(numeric(),4,0),comp$event_types,feature_order=character(),causes=c('default','exit'),ties='breslow',target=comp$target,training=comp$training,model_id='shared-prior-first-exit',model_version='1')
 curves<-predict_event_curves(cause,list(list(path_id='facility_A',start=0,stop=60,covariates=list(),stratum='all',covariate_time=0)),c(0,30,60),feature_order=character(),target=comp$target)$value
 eid<-data$open_episode$episode_id;default<-list(episode_id=eid,entity_id='facility_A',default_at='2024-09-01',known_at='2024-09-02',ead=95000,currency='EUR');flows<-lapply(life$realized_recovery$cashflows,function(f)list(cashflow_id=f$cashflow_id,episode_id=eid,cashflow_at=f$cashflow_date,known_at=f$known_at,amount=f$amount,kind='recovery',currency='EUR'))
 known<-build_recovery_episodes(list(default),flows,cures=list(),evaluation_cutoff='2024-10-01')$value;final<-build_recovery_episodes(list(default),flows,cures=list(),evaluation_cutoff='2025-09-30')$value
 openargs<-list(episodes=list(data$open_episode),cashflows=list(),fitted_recovery_model=data$residual_model,X=matrix(numeric(),1,0),valuation_contracts=list(data$valuation),future_cost_cashflows=list(),feature_order=character(),expected_target=data$recovery_target,stage_spec=data$stage_spec,as_of='2024-10-01',currency='EUR',extrapolation='parametric');opened<-do.call(estimate_open_workout_lgd,openargs)$value
 bad<-openargs;bad$valuation_contracts[[1]]['tail_discount_factor']<-list(NULL);bad$valuation_contracts[[1]]['tail_assumption_reference']<-list(NULL);unidentified<-do.call(estimate_open_workout_lgd,bad)$value
 amount<-cure$expected_recovery;base<-.2*95000
 treatment_args<-list(treatment_candidates=list(list(treatment_id='plan_A',version='1',known_at='2024-09-05',subject_id='facility_A',currency='EUR',action='TEMPORARY_REDUCTION',prediction_reference='transferred-cure-model-monetary-scenario',support_status='SUPPORTED',affordability_status='AFFORDABLE',eligibility_status='ELIGIBLE',uptake_probability=.25,offer_cost=10,accepted_upfront_cost=100,rejected_present_value=base,cashflows=list(list(cashflow_id='assumed-terminal',date='2024-11-30',expected_recovery=amount,expected_cost=0,discount_factor=1)))),treatment_profile=list(profile_id='mortgage-offer-scenario',version='1',known_at='2024-09-05',currency='EUR',subject_id='facility_A',baseline_id='no-change',baseline_present_value=base,identification='CONDITIONAL_SCENARIO_NOT_CAUSAL',allowed_actions=list('TEMPORARY_REDUCTION')),as_of='2024-10-01')
 treatment<-do.call(evaluate_treatment_candidates,treatment_args)$value
 action<-list(action_id='plan_A',currency='EUR',uptake_probability=.25,offer_cost=10,support_status='SUPPORTED',assumption_reference=data$assumption_reference,accepted_scenarios=list(list(scenario_id='conditional-mean',probability=1,cashflows=list(list(cashflow_id='accepted-recovery',kind='RECOVERY',period_end='2024-11-30',amount=amount),list(cashflow_id='accepted-cost',kind='COST',period_end='2024-11-30',amount=100)))),declined_scenarios=list(list(scenario_id='baseline',probability=1,cashflows=list(list(cashflow_id='declined-recovery',kind='RECOVERY',period_end='2024-11-30',amount=base)))))
 value<-expected_collections_value(list(action),1,ead=95000,currency='EUR',period_end_dates='2024-11-30')$value
 eventloss<-event_conditioned_loss(list(list(state_id='survive',events=list(default=FALSE),probability=1-pd,conditional_loss=0),list(state_id='default',events=list(default=TRUE),probability=pd,conditional_loss=raw$closed_workout$economic_loss)),event_names='default',currency='EUR',probability_measure='PHYSICAL')$value
 transitions<-list(list(from_state='DRAFT',to_state='FINAL',event_type='approve',required_gates=list('original_approved')),list(from_state='FINAL',to_state='SUPERSEDED',event_type='settle',required_gates=list('settlement_closed')))
 approved<-transition_assessment_state(assessment,list(event_id='actual-approval',type='approve',occurred_at='2024-02-01',known_at='2024-02-01',reason='Original actual application decision',gates=list(original_approved=raw$retail$decision_artifacts[[1]]$action=='APPROVE')),transitions)$value
 settled<-transition_assessment_state(approved,list(event_id='actual-closure',type='settle',occurred_at='2025-09-15',known_at='2025-09-30',reason='Actual settled mortgage claim',gates=list(settlement_closed=TRUE)),transitions)$value
 position<-list(position_id='facility_A',claim_id='facility_A-claim',facility_id='facility_A',facility_ead=100000,sector='residential_mortgage',region='synthetic-region',exposure_basis='GROSS',collateral_treatment='ALREADY_IN_CONDITIONAL_LGD',entity_id='customer_A',household_id='household_A',currency='EUR',ead=100000)
 graph<-build_entity_graph(list(list(entity_id='customer_A')),list(),list(policy_id='no-inferred-cross-default',version='1',edge_types=list('CROSS_DEFAULT')),as_of='2024-02-03',known_at='2024-02-03')
 portfolio<-prepare_credit_portfolio(list(position),graph,list(policy_id='legal-groups',version='1',edge_types=list('CROSS_DEFAULT'),direction_policy='mutual_only',transitive=TRUE),list(portfolio_id='mortgage-facility_A',version='1',currency='EUR',as_of='2024-02-03',known_at='2024-02-03',horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='initially_performing',event='first_default'))$value
 concentration<-credit_concentration_measures(list(position),weight_field='ead',group_fields='household_id',weight_unit='EUR')$value
 cohort<-pool$cohort[[1]];observation<-list(observation_id='facility_A',facility_id='facility_A',as_of=cohort$index_date,performance_start=cohort$index_date,outcome_end=cohort$label_window_end,eligible=TRUE,prior_default=FALSE,target=1,outcome_known_at=cohort$label_known_at,default_definition=pool$fit$target$default_definition,cohort='2024-02');pred<-list(observation_id='facility_A',pd=pd,forecast_at=cohort$index_date,known_at=cohort$index_date,default_definition=observation$default_definition,horizon_days=365,unit='facility',probability_measure='PHYSICAL',model_id=forecast$model_id,model_version='1')
 count<-default_count_backtest(list(observation),list(pred),'cohort',unit='facility',horizon_days=365,default_definition=observation$default_definition,redefault_policy='exclude_previous_default',evaluation_cutoff='2025-09-30')$value
 pi<-raw$pool_inputs;estimated<-estimate_pool_risk_parameters(pi$pool_assignments,pi$cohort_outcomes,pi$workouts,pi$estimation_profile,evaluation_cutoff='2025-09-30',calibration_id='observed-mortgage-diagnostic',calibration_version='1')$value
 out<-list(data_origin='SYNTHETIC',facility_id='facility_A',freshness=fresh,feature_drift=drift,calibration_drift=calibration,roll_rates=roll,cure_prediction=cure,observed_cure_targets=targets,competing_exit_curves=curves,known_recovery_episodes=known,final_recovery_episodes=final,open_recovery_scenario=opened,unidentified_tail=unidentified,open_recovery_identification='CONDITIONAL_SCENARIO_ONLY: interim principal/cash reconciliation unavailable; not identified actual open LGD',treatment=treatment,collections_value=value,event_conditioned_realized_loss=eventloss,assessment_final_state=settled$state,portfolio=portfolio,concentration=concentration,default_count=count,observed_pool_parameters=estimated,assumption_reference=data$assumption_reference)
 if(verify_reference)stopifnot(fresh$status=='STALE',settled$state=='SUPERSEDED',identical(unlist(cure$sustained_cure_probability),c(0,.5,.5)),identical(unlist(cure$cure_then_redefault_probability),c(0,0,.5)),amount==38000,is.null(targets[[1]]$cure_label),value[[1]]$expected_net_recovery==23715,abs(curves$curves[[1]]$cumulative_incidence$default[[2]]-.5*(1-exp(-.5)))<1e-12,eventloss$expected_loss==8000,count$overall$observed_defaults==1,is.null(unidentified$episodes[[1]]$expected_final_lgd))
 if(return_artifacts)out$raw_artifacts<-list(main=raw,cure_model=model,cause_model=cause$model,open_inputs=openargs,treatment_inputs=treatment_args,collections_input=action)
 out
}
